package com.townyreborn.staffconnector;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.bukkit.configuration.file.YamlConfiguration;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.*;
import static org.junit.jupiter.api.Assertions.*;

class JourneyInsightsTest {
    @TempDir Path folder;
    static final String UUID="00112233-4455-6677-8899-aabbccddeeff";
    static YamlConfiguration config(){var y=new YamlConfiguration();y.set("journey.steps",116);y.set("journey.points-first",150);y.set("journey.points-increase",30);return y;}
    static YamlConfiguration receipt(Map<String,Object> old,Map<String,Object> current){var y=new YamlConfiguration();y.set("schema",1);y.set("uuid",UUID);y.set("sequence",1);y.set("event-id","journey-"+UUID+"-1");y.set("occurred-at","2026-10-14T20:00:00Z");y.createSection("before",old);var data=new LinkedHashMap<>(current);data.put("name","FixturePlayer");y.createSection("after",data);return y;}
    static double total(List<Map<String,Object>> events,String metric){return events.stream().filter(r->metric.equals(r.get("metric"))).mapToDouble(r->((Number)r.get("value")).doubleValue()).sum();}
    @Test void historicalCreditAndNewSourcePointsRemainSeparate(){var r=receipt(Map.of("points",100,"day","2026-10-14"),Map.of("points",1130,"history-credit-points",1000,"day","2026-10-14","daily-awards",Map.of("quests",10,"jobs",12,"fishing",3,"playtime",5)));var events=JourneyInsights.events(r,config());assertEquals(30,total(events,"journey_jp"));assertEquals(1000,total(events,"journey_history_restored"));assertEquals(0,total(events,"journey_perk_purchases"));}
    @Test void exactSavedPaymentWinsOverCurrentCataloguePrice(){var prepared=Map.of("pending-purchase",Map.of("perk","eglow","phase","PREPARED","price",19999));var debited=Map.of("pending-purchase",Map.of("perk","eglow","phase","DEBITED","price",19999));var payment=JourneyInsights.events(receipt(new HashMap<>(prepared),new HashMap<>(debited)),config());var delivery=JourneyInsights.events(receipt(new HashMap<>(debited),Map.of("owned-perks",List.of("eglow"))),config());assertEquals(1,total(delivery,"journey_perk_purchases"));assertEquals(19999,total(payment,"journey_money_spent"));assertEquals(0,total(delivery,"journey_money_spent"));}
    @Test void aSavedDebitIsVisibleEvenWhilePermissionDeliveryIsPending(){var rows=JourneyInsights.events(receipt(Map.of("pending-purchase",Map.of("perk","eglow","phase","PREPARED")),Map.of("pending-purchase",Map.of("perk","eglow","phase","DEBITED","price",20000))),config());assertEquals(20000,total(rows,"journey_money_spent"));assertEquals(0,total(rows,"journey_perk_purchases"));}
    @Test void retainedOwnershipCannotManufactureAPayment(){var rows=JourneyInsights.events(receipt(Map.of(),Map.of("owned-perks",List.of("fly"),"unlocked-perks",List.of("fly"))),config());assertEquals(1,total(rows,"journey_ownership_restored"));assertEquals(0,total(rows,"journey_perk_purchases"));assertEquals(0,total(rows,"journey_money_spent"));}
    @Test void rewardReceiptPreservesConfirmedMoneyAndTownChunks(){var rows=JourneyInsights.events(receipt(Map.of("pending-gift","milestone_116","pending-gift-money",100000,"pending-gift-town-blocks",5,"pending-gift-commands",List.of("cratekey give FixturePlayer vote 1")),Map.of("claimed-gifts",List.of("milestone_116"))),config());assertEquals(1,total(rows,"journey_rewards_claimed"));assertEquals(100000,total(rows,"journey_reward_money"));assertEquals(5,total(rows,"journey_reward_chunks"));assertTrue(rows.stream().filter(r->"journey_rewards_claimed".equals(r.get("metric"))).anyMatch(r->!((List<?>)((Map<?,?>)r.get("details")).get("commands")).isEmpty()));}
    @Test void earlierRewardMarkersCannotCountAsNewDeliveries(){var rows=JourneyInsights.events(receipt(Map.of(),Map.of("claimed-gifts",List.of("milestone_001"))),config());assertEquals(1,total(rows,"journey_reward_receipts_restored"));assertEquals(0,total(rows,"journey_rewards_claimed"));}
    @Test void all116LevelThresholdsMatchThePublishedCurve(){for(int l=1;l<=116;l++){long points=150L*(l-1)+30L*(l-1)*(l-2)/2;assertEquals(l,JourneyInsights.level(points,config()));if(l>1)assertEquals(l-1,JourneyInsights.level(points-1,config()));}}
    @Test void futureConfiguredLevelsAboveOneThousandRemainSupported(){var y=config();y.set("journey.steps",1500);int level=1200;long points=150L*(level-1)+30L*(level-1)*(level-2)/2;assertEquals(level,JourneyInsights.level(points,y));}
    @Test void replayKeepsEveryMetricIdentity(){var r=receipt(Map.of(),Map.of("points",10,"day","2026-10-14","daily-awards",Map.of("quests",10)));assertEquals(JourneyInsights.events(r,config()),JourneyInsights.events(r,config()));}
    @Test void failedDurableHandoverKeepsOriginalReceipt()throws Exception{Path game=folder.resolve("game");Files.createDirectories(game.resolve("journeydata"));Files.createDirectories(game.resolve("staff-audit/"+UUID));Files.writeString(game.resolve("config.yml"),config().saveToString());Path source=game.resolve("staff-audit/"+UUID+"/1.yml");Files.writeString(source,receipt(Map.of(),Map.of("points",10,"daily-awards",Map.of("quests",10))).saveToString());Path transport=folder.resolve("transport");Files.createDirectories(transport);Files.createDirectory(transport.resolve("insights-outbox.json.tmp"));try(var out=new InsightsOutbox(transport,e->false,Logger.getAnonymousLogger())){var reader=new JourneyInsights(out,Logger.getAnonymousLogger());reader.configure(game);reader.read();assertTrue(Files.exists(source));}}
    @Test void successfulHandoverPersistsBeforeAcknowledgingAndProfilesStayUnchanged()throws Exception{Path game=folder.resolve("game");Files.createDirectories(game.resolve("journeydata"));Files.createDirectories(game.resolve("staff-audit/"+UUID));Files.writeString(game.resolve("config.yml"),config().saveToString());Path source=game.resolve("staff-audit/"+UUID+"/1.yml");Files.writeString(source,receipt(Map.of(),Map.of("points",10,"daily-awards",Map.of("quests",10))).saveToString());Path profile=game.resolve("journeydata/"+UUID+".yml");Files.writeString(profile,"schema: 2\nuuid: "+UUID+"\npoints: 10\n");byte[] original=Files.readAllBytes(profile);Path transport=folder.resolve("transport");Files.createDirectories(transport);try(var out=new InsightsOutbox(transport,e->false,Logger.getAnonymousLogger())){var reader=new JourneyInsights(out,Logger.getAnonymousLogger());reader.configure(game);reader.read();assertFalse(Files.exists(source));assertTrue(Files.readString(transport.resolve("insights-outbox.json")).contains("journey_jp"));reader.read();assertArrayEquals(original,Files.readAllBytes(profile));}}
    @Test void interruptedProfileWriteCannotTransferAnUncommittedReceipt()throws Exception{Path game=folder.resolve("game");Files.createDirectories(game.resolve("journeydata"));Files.createDirectories(game.resolve("staff-audit/"+UUID));Files.writeString(game.resolve("config.yml"),config().saveToString());Path source=game.resolve("staff-audit/"+UUID+"/1.pending");Files.writeString(source,receipt(Map.of(),Map.of("points",10)).saveToString());Files.writeString(game.resolve("journeydata/"+UUID+".yml"),"schema: 2\nuuid: "+UUID+"\nstaff-audit-sequence: 0\n");Path transport=folder.resolve("transport");Files.createDirectories(transport);try(var out=new InsightsOutbox(transport,e->false,Logger.getAnonymousLogger())){var reader=new JourneyInsights(out,Logger.getAnonymousLogger());reader.configure(game);reader.read();assertTrue(Files.exists(source));assertTrue(out.checkpoint());assertFalse(Files.readString(transport.resolve("insights-outbox.json")).contains("journey_profile_commit"));}}
    @Test void unchangedProfilesDoNotResendTheFullCatalogueEachMinute()throws Exception{Path game=folder.resolve("game");Files.createDirectories(game.resolve("journeydata"));Files.writeString(game.resolve("config.yml"),config().saveToString());Path profile=game.resolve("journeydata/"+UUID+".yml");Files.writeString(profile,"schema: 2\nuuid: "+UUID+"\npoints: 10\n");Path transport=folder.resolve("transport");Files.createDirectories(transport);try(var out=new InsightsOutbox(transport,e->false,Logger.getAnonymousLogger())){var reader=new JourneyInsights(out,Logger.getAnonymousLogger());reader.configure(game);reader.read();int before=out.buffered();var time=JourneyInsights.class.getDeclaredField("nextSnapshots");time.setAccessible(true);time.setLong(reader,0);reader.read();assertEquals(before,out.buffered());Files.writeString(profile,"schema: 2\nuuid: "+UUID+"\npoints: 999\n");time.setLong(reader,0);reader.read();assertEquals(before+1,out.buffered());}}
    @Test void sentinelDamageCannotPoisonHealthyTelemetry(){var delivered=new ArrayList<Map<String,Object>>();try(var buffer=new TelemetryBuffer(e->{delivered.add(e);return true;})){buffer.record("Jobs","money_paid","",null,"","",5,Map.of());buffer.record("Minecraft","damage_received","",null,"","",Float.MAX_VALUE,Map.of());buffer.record("Minecraft","player_deaths","",null,"","",1,Map.of());buffer.flush();assertEquals(2,((List<?>)delivered.getFirst().get("samples")).size());assertEquals(1,buffer.rejected());}}
    @Test void repairKeepsHealthyRowsAndUsesAStableNewIdentity(){var good=Map.of("metric","money_paid","value",5,"count",1,"min",5,"max",5);var bad=Map.of("metric","damage_received","value",Float.MAX_VALUE,"count",1,"min",Float.MAX_VALUE,"max",Float.MAX_VALUE);var archive=Map.of("validation_error","invalid_numeric_metric","event",Map.of("type","telemetry.batch","event_id","original","samples",List.of(good,bad)));var repaired=TelemetryRepair.repair(archive);assertEquals(List.of(good),repaired.get("samples"));assertEquals(repaired,TelemetryRepair.repair(archive));assertNull(TelemetryRepair.repair(Map.of("validation_error","other_error")));}
    @Test void flappingHttpFailuresDoNotRestartWarningSpam(){var messages=new ArrayList<LogRecord>();var log=Logger.getAnonymousLogger();log.setUseParentHandlers(false);log.addHandler(new Handler(){public void publish(LogRecord r){messages.add(r);}public void flush(){}public void close(){}});var now=new AtomicLong();var warnings=new ConnectionWarnings(log,now::get);for(int n=0;n<20;n++){now.set(n*30);warnings.failed("HTTP 500");warnings.healthy();}assertEquals(1,messages.size());now.set(700);warnings.healthy();assertEquals(2,messages.size());now.set(710);warnings.failed("HTTP 502");assertEquals(3,messages.size());}
}
